A current successful request displays its result and clears the error. A current failed request displays an error. A successful retry clears that error. Older success or failure must not replace newer state. Only the Python component is in scope; no browser or backend is available.
# Catalog lookup
Python standard library only. The UI displays Lookup.result and Lookup.error directly. QA files may be added at the project root.
class Lookup:
    def __init__(self):
        self.result = None
        self.error = None
        self.generation = 0

    async def run(self, query, fetch):
        self.generation += 1
        generation = self.generation
        try:
            value = await fetch(query)
        except RuntimeError as error:
            if generation == self.generation:
                self.error = str(error)
            return
        if generation == self.generation:
            self.result = value
